<script setup lang="ts">
import { computed, ref } from 'vue'
import type { Config, Plan, PlanItem, Queue, Slot } from './types'

const props = defineProps<{ config: Config; selectedPlanId: string | null; busy: boolean }>()
const emit = defineEmits<{ save: []; 'update:selectedPlanId': [string | null] }>()
const days = ['一', '二', '三', '四', '五', '六', '日']
const hours = Array.from({ length: 24 }, (_, index) => String(index).padStart(2, '0'))
const minutes = Array.from({ length: 60 }, (_, index) => String(index).padStart(2, '0'))
const selectedPlan = computed(() => props.config.plans.find((item) => item.id === props.selectedPlanId) || null)
const draggedSlotId = ref<string | null>(null)
const draggedItemId = ref<string | null>(null)
function uid() { return crypto.randomUUID() }
function persist() { emit('save') }
function choosePlan(id: string | null) { emit('update:selectedPlanId', id) }
function newPlan() {
  if (props.config.queues.length < 2) return
  const plan: Plan = { id: uid(), name: '新计划', items: props.config.queues.slice(0, 2).map((script) => ({ id: uid(), script_id: script.id, days: [0, 1, 2, 3, 4, 5, 6] })), time_slots: [], startup_mode: 'never', scheduled_enabled: true, completion_action: 'none', completion_delay_minutes: 0, script_ids: [], run_on_startup: false }
  props.config.plans.push(plan); choosePlan(plan.id); persist()
}
function deletePlan() { const id = selectedPlan.value?.id; if (!id) return; props.config.plans = props.config.plans.filter((item) => item.id !== id); choosePlan(props.config.plans[0]?.id || null); persist() }
function scriptFor(item: PlanItem) { return props.config.queues.find((script) => script.id === item.script_id) || null }
function addSlot(plan: Plan) { plan.time_slots.push({ id: uid(), enabled: true, days: [0, 1, 2, 3, 4, 5, 6], time: '09:00' }); persist() }
function removeSlot(plan: Plan, id: string) { plan.time_slots = plan.time_slots.filter((item) => item.id !== id); persist() }
function addItem(plan: Plan, event: Event) { const scriptId = (event.target as HTMLSelectElement).value; if (!scriptId || plan.items.some((item) => item.script_id === scriptId)) return; plan.items.push({ id: uid(), script_id: scriptId, days: [0, 1, 2, 3, 4, 5, 6] }); (event.target as HTMLSelectElement).value = ''; persist() }
function removeItem(plan: Plan, id: string) { plan.items = plan.items.filter((item) => item.id !== id); persist() }
function moveItem(plan: Plan, index: number, direction: -1 | 1) { const target = index + direction; if (target < 0 || target >= plan.items.length) return; [plan.items[index], plan.items[target]] = [plan.items[target], plan.items[index]]; persist() }
function moveBefore<T extends { id: string }>(items: T[], fromId: string | null, targetId: string) { const from = items.findIndex((item) => item.id === fromId); const target = items.findIndex((item) => item.id === targetId); if (from < 0 || target < 0 || from === target) return; const [moved] = items.splice(from, 1); items.splice(target, 0, moved); persist() }
function setTime(slot: Slot, part: 'hour' | 'minute', value: string) { const [hour, minute] = slot.time.split(':'); slot.time = `${part === 'hour' ? value : hour}:${part === 'minute' ? value : minute}`; persist() }
function setStartup(plan: Plan) { if (plan.startup_mode !== 'never') props.config.plans.forEach((item) => { if (item.id !== plan.id) item.startup_mode = 'never' }); persist() }
function issue(plan: Plan) { const ids = plan.items.map((item) => item.script_id); if (ids.length < 2) return '至少需要两个软件脚本'; if (new Set(ids).size !== ids.length) return '不能重复添加同一软件脚本'; if (ids.some((id) => !props.config.queues.some((script) => script.id === id))) return '包含已删除的软件脚本'; return '' }
function next(plan: Plan) { const slot = plan.scheduled_enabled && plan.time_slots.find((item) => item.enabled); return slot ? `${slot.days.map((day) => `周${days[day]}`).join('、')} ${slot.time}` : '未设置' }
</script>

<template>
  <section class="queue-page" aria-label="计划管理">
    <div class="queue-page-head"><div><h2>计划队列</h2><p>定时触发后按任务列表顺序执行符合当天星期的软件。</p></div><div><button v-if="selectedPlan" class="danger" :disabled="busy" @click="deletePlan">删除当前计划</button><button class="primary" :disabled="busy || config.queues.length < 2" :title="config.queues.length < 2 ? '至少需要两个软件脚本' : ''" @click="newPlan">＋ 新建计划</button></div></div>
    <section v-if="!config.plans.length" class="queue-empty"><div class="queue-empty-mark" aria-hidden="true">△</div><h3>暂无计划</h3><p>还没有创建任何计划。</p></section>
    <template v-else>
      <section class="queue-selector"><div class="queue-selector-title"><h3>计划选择</h3><span>{{ config.plans.length }} 个计划</span></div><div class="queue-selector-items"><button v-for="plan in config.plans" :key="plan.id" :class="{ active: plan.id === selectedPlanId }" @click="choosePlan(plan.id)"><b>{{ plan.name }}</b><small>{{ plan.items.length }} 个软件 · 下次：{{ next(plan) }}</small><em :class="{ invalid: !!issue(plan) }">{{ issue(plan) || '可运行' }}</em></button></div></section>
      <section v-if="selectedPlan" class="queue-detail"><header><div><h3>{{ selectedPlan.name }}</h3><small>配置修改会自动保存；运行期间锁定。</small></div><label class="queue-name">队列名称<input v-model="selectedPlan.name" :disabled="busy" @change="persist"></label></header><div class="queue-settings-grid"><label>队列类型<select :value="'scheduled'" :disabled="busy" aria-label="队列类型"><option value="scheduled">定时队列</option><option value="loop" disabled>循环队列（下一版本提供）</option></select></label><label>启动时运行<select v-model="selectedPlan.startup_mode" :disabled="busy" @change="setStartup(selectedPlan)"><option value="never">否</option><option value="always">是</option><option value="daily_first">每日首次启动时</option></select></label><label>定时运行<select v-model="selectedPlan.scheduled_enabled" :disabled="busy" @change="persist"><option :value="true">是</option><option :value="false">否</option></select></label><label>完成后操作<select v-model="selectedPlan.completion_action" :disabled="busy" @change="persist"><option value="none">无操作</option><option value="shutdown">关机</option><option value="force_shutdown">强制关机</option><option value="restart">重启</option><option value="hibernate">休眠</option><option value="sleep">睡眠</option><option value="exit_app">退出软件</option><option value="logoff">注销此账户</option></select></label><label>延时执行（分钟）<input v-model.number="selectedPlan.completion_delay_minutes" type="number" min="0" max="10080" :disabled="busy || selectedPlan.completion_action === 'none'" @change="persist"><small>完成后等待，再进入 60 秒可取消倒计时。</small></label></div><p v-if="issue(selectedPlan)" class="queue-diagnostic">{{ issue(selectedPlan) }}</p>
        <section class="queue-table-section"><div class="queue-table-heading"><h3>定时列表</h3><button :disabled="busy" @click="addSlot(selectedPlan)">＋ 添加定时</button></div><div v-if="!selectedPlan.time_slots.length" class="table-empty">尚未设置定时。</div><div v-else class="queue-table"><div class="queue-table-head"><span>序号</span><span>状态</span><span>执行周期</span><span>执行时间</span><span>操作</span></div><article v-for="(slot, index) in selectedPlan.time_slots" :key="slot.id" class="queue-table-row" :draggable="!busy" @dragstart="draggedSlotId = slot.id" @dragover.prevent @drop="moveBefore(selectedPlan.time_slots, draggedSlotId, slot.id)"><b class="drag-order" title="拖拽调整顺序">⋮⋮ {{ index + 1 }}</b><label><input v-model="slot.enabled" type="checkbox" :disabled="busy" @change="persist">启用</label><details class="day-picker"><summary>{{ slot.days.map((day) => `周${days[day]}`).join('、') }}</summary><div><label v-for="(name, day) in days" :key="name"><input v-model="slot.days" :value="day" type="checkbox" :disabled="busy" @change="persist">周{{ name }}</label></div></details><div class="time-picker"><select :value="slot.time.split(':')[0]" :disabled="busy" aria-label="小时" @change="setTime(slot, 'hour', ($event.target as HTMLSelectElement).value)"><option v-for="hour in hours" :key="hour" :value="hour">{{ hour }} 时</option></select><select :value="slot.time.split(':')[1]" :disabled="busy" aria-label="分钟" @change="setTime(slot, 'minute', ($event.target as HTMLSelectElement).value)"><option v-for="minute in minutes" :key="minute" :value="minute">{{ minute }} 分</option></select></div><button class="textdanger" :disabled="busy" @click="removeSlot(selectedPlan, slot.id)">删除</button></article></div></section>
        <section v-if="selectedPlan.time_slots.length" class="queue-table-section"><div class="queue-table-heading"><h3>任务列表</h3><select :disabled="busy" @change="addItem(selectedPlan, $event)"><option value="">＋ 添加任务</option><option v-for="script in config.queues.filter((script) => !selectedPlan!.items.some((item) => item.script_id === script.id))" :key="script.id" :value="script.id">{{ script.name }}</option></select></div><div class="queue-table"><div class="queue-table-head task-head"><span>序号</span><span>软件脚本</span><span>运行周几</span><span>操作</span></div><article v-for="(item, index) in selectedPlan.items" :key="item.id" class="queue-table-row task-row" :draggable="!busy" @dragstart="draggedItemId = item.id" @dragover.prevent @drop="moveBefore(selectedPlan.items, draggedItemId, item.id)"><b class="drag-order" title="拖拽调整顺序">⋮⋮ {{ index + 1 }}</b><span>{{ scriptFor(item)?.name || '已删除的软件脚本' }}</span><details class="day-picker"><summary>{{ item.days.map((day) => `周${days[day]}`).join('、') }}</summary><div><label v-for="(name, day) in days" :key="name"><input v-model="item.days" :value="day" type="checkbox" :disabled="busy" @change="persist">周{{ name }}</label></div></details><span class="row-actions"><button :disabled="busy || index === 0" @click="moveItem(selectedPlan, index, -1)">上移</button><button :disabled="busy || index === selectedPlan.items.length - 1" @click="moveItem(selectedPlan, index, 1)">下移</button><button class="textdanger" :disabled="busy" @click="removeItem(selectedPlan, item.id)">删除</button></span></article></div></section>
      </section>
    </template>
  </section>
</template>

<style scoped>
.queue-page{max-width:1470px;margin:0 auto;padding-bottom:48px}.queue-page-head,.queue-table-heading,.queue-selector-title,.queue-detail>header{display:flex;align-items:center;justify-content:space-between;gap:16px}.queue-page-head h2{margin:0;font-size:28px}.queue-page-head p,.queue-detail header small{color:#8bb8d5}.queue-page-head>div:last-child{display:flex;gap:10px}.queue-empty,.queue-selector,.queue-detail{border:1px solid #284b63;background:#102333;border-radius:10px}.queue-empty{min-height:390px;display:grid;place-content:center;text-align:center;color:#8bb8d5}.queue-empty-mark{font-size:52px;line-height:1;color:#40d7ca;filter:drop-shadow(0 0 14px #40d7ca66)}.queue-empty h3{color:#eff7fb;margin:14px 0 4px}.queue-selector{margin-top:20px}.queue-selector-title{padding:18px 22px;border-bottom:1px solid #29465b}.queue-selector-title h3,.queue-detail h3{margin:0}.queue-selector-title span{color:#57dccc;background:#113f3c;padding:3px 8px;border-radius:4px}.queue-selector-items{display:flex;flex-wrap:wrap;gap:12px;padding:18px 22px}.queue-selector-items button{min-width:210px;text-align:left;background:#0c1c29;border:1px solid #31546b;border-radius:7px;padding:13px;color:#eaf6ff}.queue-selector-items button.active{border-color:#35d8cb;box-shadow:inset 3px 0 #35d8cb}.queue-selector-items small,.queue-selector-items em{display:block;margin-top:5px;color:#91b7cc;font-style:normal}.queue-selector-items em.invalid{color:#ffc155}.queue-detail{margin-top:20px}.queue-detail>header{padding:20px 22px;border-bottom:1px solid #29465b}.queue-name{display:grid;gap:6px;min-width:280px;color:#b6d8e9;font-size:12px}.queue-settings-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;padding:22px;border-bottom:1px solid #29465b}.queue-settings-grid label{display:grid;gap:7px;color:#b6d8e9}.queue-settings-grid small{color:#79a3bb}.queue-settings-grid input,.queue-settings-grid select{min-width:0}.queue-diagnostic{margin:0;padding:12px 22px;background:#3a2b12;color:#ffd26a}.queue-table-section{padding:22px;border-bottom:1px solid #29465b}.queue-table-section:last-child{border-bottom:0}.queue-table-heading{margin-bottom:14px}.queue-table{border:1px solid #29465b;border-radius:7px;overflow:visible}.queue-table-head,.queue-table-row{display:grid;grid-template-columns:84px 140px minmax(250px,1fr) 220px 110px;align-items:center;gap:12px;padding:12px 14px}.queue-table-head{background:#0d1b27;color:#bbd9e8;font-weight:700}.queue-table-row{border-top:1px solid #29465b;min-height:58px}.task-head,.task-row{grid-template-columns:84px minmax(230px,1fr) minmax(260px,1fr) 220px}.day-picker{position:relative}.day-picker summary{cursor:pointer;color:#dceef8;list-style:none}.day-picker summary::after{content:' ▾';color:#43d6ca}.day-picker>div{position:absolute;z-index:4;min-width:220px;display:grid;grid-template-columns:repeat(2,1fr);gap:8px;padding:12px;top:calc(100% + 8px);background:#14253a;border:1px solid #3a6180;border-radius:6px;box-shadow:0 14px 30px #0008}.day-picker label{white-space:nowrap}.time-picker{display:flex;gap:7px}.time-picker select{min-width:92px}.row-actions{display:flex;gap:6px;flex-wrap:wrap}.table-empty{min-height:95px;display:grid;place-items:center;border:1px dashed #31546b;color:#88adbf}.textdanger{color:#ff8795}@media(max-width:980px){.queue-settings-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.queue-table{border:0}.queue-table-head{display:none}.queue-table-row,.task-row{grid-template-columns:1fr;gap:9px;border:1px solid #29465b;border-radius:7px;margin:10px 0}.queue-table-row>b::before{content:'序号 ';color:#86adc4}.day-picker>div{position:static;margin-top:8px}.queue-page-head,.queue-detail>header{align-items:flex-start;flex-direction:column}.queue-name{width:100%}}@media(max-width:620px){.queue-settings-grid{grid-template-columns:1fr}.queue-page-head>div:last-child{width:100%}.queue-page-head button{flex:1}.queue-selector-items button{width:100%}}
</style>
